import {createGame,move,setPause,MAPS,energy,invariants,predict,frustratedBonds,mismatch} from './snake-model.js';
const $=id=>document.getElementById(id),canvas=$('board'),ctx=canvas.getContext('2d');
let lesson='retrace',map='neel',seed=17,s,dir='right',timer=null,lastMove=0,flash=0;
const LESSONS={retrace:{title:'走出三格，再原路回来',text:'按 → → → ← ← ←。交换能先上升，再回到零；每一枚自旋都回到原位。',path:['right','right','right','left','left','left']},loop:{title:'六步之后，洞挪了，背景没乱',text:'按 → ↑ ← ↓ → ↑。第四步回到起点还没修好；再走两步才完成对角迁移。',path:['right','up','left','down','right','up']},wall:{title:'沿着墙向上走四格',text:'试试 ↑ ↑ ↑ ↑：理想直墙的交换能先付 0.5 Jz，之后保持不变。重置后再试离墙走。',path:['up','up','up','up']},relay:{title:'接力所有金环空穴，再回到出口',text:'方向指向相邻空穴时，只交接控制权。收集标记不吞洞、不补自旋；保持所有守恒量，回到方形起点。',path:[]}};
const arrow={up:'↑',right:'→',down:'↓',left:'←'};
const signed=n=>(n>0?'+':'')+n.toFixed(1);
function reset(){map=lesson==='wall'?'wall':lesson==='relay'?$('map').value:'neel';s=createGame({map,lesson,seed});dir=lesson==='wall'?'up':'right';$('auto').checked=false;stopAuto();$('map-options').classList.toggle('visible',lesson==='relay');document.querySelectorAll('[data-lesson]').forEach(b=>{b.classList.toggle('active',b.dataset.lesson===lesson);b.setAttribute('aria-pressed',String(b.dataset.lesson===lesson));});$('mission-title').textContent=LESSONS[lesson].title;$('mission-text').textContent=LESSONS[lesson].text;$('path-hint').innerHTML=LESSONS[lesson].path.map(d=>`<b>${arrow[d]}</b>`).join('');render();}
function act(d){dir=d;const res=move(s,d);lastMove=performance.now();flash=res.ok?1:0;if(['won','lost'].includes(s.status)){stopAuto();$('auto').checked=false;}render();}
function pause(){setPause(s,s.status!=='paused');if(s.status==='paused')stopAuto();else if($('auto').checked)startAuto();render();}
function stopAuto(){if(timer)clearTimeout(timer);timer=null;}
function startAuto(){stopAuto();if(!['won','lost','paused'].includes(s.status)&&$('auto').checked)timer=setTimeout(()=>{act(dir);startAuto();},480+Math.max(0,s.tension)*30);}
function render(){
 $('board-name').textContent=MAPS[s.map].name;$('step-count').textContent=`${s.steps} / ${s.maxSteps} 步`;$('event').textContent=s.status==='paused'?'已暂停。按空格或“继续”恢复。':s.event;$('energy').textContent=signed(s.relativeEnergy);$('delta').textContent=signed(s.lastDelta);$('energy-meter').style.width=`${Math.min(100,100*s.tension/s.limit)}%`;$('energy-meter').style.background=s.tension>s.limit*.8?'#cc8154':'#92ae6d';$('budget').textContent=s.limit;$('collection').textContent=lesson==='relay'?`${s.collected} / ${s.goal}`:'单洞';$('score').textContent=s.score;$('pause').textContent=s.status==='paused'?'继续':'暂停';
 const inv=invariants(s);$('holes').textContent=inv.holes;$('spin-count').textContent=`${inv.up} / ${inv.down}`;$('sz').textContent=inv.sz;const preserved=JSON.stringify(inv)===JSON.stringify(s.initialInvariants);$('conserved').textContent=preserved?'● 守恒检查通过':'⚠ 守恒检查异常';
 for(const d of Object.keys(arrow)){const cost=predict(s,d);$('cost-'+d).textContent=cost===null?'边界':signed(cost);}
 const done=['won','lost'].includes(s.status);$('end-card').hidden=!done;if(done){$('end-label').textContent=s.status==='won'?'EXPERIMENT COMPLETE':'TRY ANOTHER PATH';$('end-title').textContent=s.status==='won'?'这条路，你解开了。':'换条路，再来一次。';$('end-copy').textContent=`${s.steps} 步 · ${s.score} 分 · 最高交换能差 ${s.peak.toFixed(1)} Jz。空穴、自旋数与总 Sz 全程守恒。`;$('next-lesson').textContent=lesson==='relay'?'换一幅磁背景 →':'下一个实验 →';}draw();
}
function draw(){const w=canvas.getBoundingClientRect().width,dpr=window.devicePixelRatio||1;if(canvas.width!==Math.round(w*dpr)){canvas.width=Math.round(w*dpr);canvas.height=canvas.width;}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,w);const pad=w*.075,cell=(w-pad*2)/s.n,point=i=>[pad+(i%s.n+.5)*cell,pad+(Math.floor(i/s.n)+.5)*cell];
 ctx.fillStyle='#132a28';ctx.fillRect(0,0,w,w);
 for(let i=0;i<s.spins.length;i++){const [x,y]=point(i);const base=((i%s.n+Math.floor(i/s.n))%2?-1:1);if(s.reference[i]!==base){ctx.fillStyle='#a7803710';ctx.fillRect(x-cell/2,y-cell/2,cell,cell);}ctx.fillStyle='#aac5ac0c';ctx.beginPath();ctx.arc(x,y,1,0,Math.PI*2);ctx.fill();}
 if($('show-bonds').checked){ctx.lineWidth=1;ctx.strokeStyle='#42615635';for(let i=0;i<s.spins.length;i++){const [x,y]=point(i);if(i%s.n<s.n-1){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+cell,y);ctx.stroke();}if(i<s.n*(s.n-1)){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x,y+cell);ctx.stroke();}}ctx.strokeStyle='#d7895888';ctx.lineWidth=Math.max(2,cell*.065);for(const [i,j] of frustratedBonds(s)){const a=point(i),b=point(j);ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke();}}
 if($('show-path').checked&&s.trail.length>1){ctx.strokeStyle='#c6e98638';ctx.lineWidth=cell*.29;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();s.trail.forEach((i,k)=>{const p=point(i);k?ctx.lineTo(...p):ctx.moveTo(...p);});ctx.stroke();}
 if(lesson==='relay'){const [x,y]=point(s.exit);ctx.strokeStyle='#c5e685aa';ctx.lineWidth=1;ctx.setLineDash([3,3]);ctx.strokeRect(x-cell*.38,y-cell*.38,cell*.76,cell*.76);ctx.setLineDash([]);}
 const bad=new Set(mismatch(s));
 for(let i=0;i<s.spins.length;i++){const [x,y]=point(i),v=s.spins[i];if(v===0){const id=s.holes.indexOf(i),active=i===s.head,claimed=s.claimed.includes(id);ctx.fillStyle='#0a1d1c';ctx.beginPath();ctx.arc(x,y,cell*.24,0,Math.PI*2);ctx.fill();ctx.lineWidth=active?2:1.5;ctx.strokeStyle=active?'#d7ee9b':claimed?'#759787':'#edba68';ctx.stroke();if(!claimed){ctx.strokeStyle='#b9854055';ctx.beginPath();ctx.arc(x,y,cell*.36,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#edba68';ctx.font=`${Math.max(6,cell*.17)}px sans-serif`;ctx.textAlign='center';ctx.fillText(id,x,y+cell*.06);}if(active){ctx.fillStyle='#dcf3a2';ctx.beginPath();ctx.arc(x,y,cell*.07,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#aacf6960';ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y,cell*.37,0,Math.PI*2);ctx.stroke();}continue;}
 if(!$('show-spins').checked)continue;ctx.strokeStyle=v===1?'#82b8a0':'#d6ad73';ctx.lineWidth=Math.max(1.4,cell*.045);const h=cell*.19,sg=v===1?-1:1;ctx.beginPath();ctx.moveTo(x,y-sg*h);ctx.lineTo(x,y+sg*h);ctx.moveTo(x-cell*.1,y+sg*h-sg*cell*.105);ctx.lineTo(x,y+sg*h);ctx.lineTo(x+cell*.1,y+sg*h-sg*cell*.105);ctx.stroke();if(bad.has(i)){ctx.fillStyle='#ee9b56';ctx.beginPath();ctx.arc(x+cell*.22,y-cell*.23,cell*.035,0,Math.PI*2);ctx.fill();}}
 if(s.status==='paused'){ctx.fillStyle='#102824a0';ctx.fillRect(0,0,w,w);ctx.fillStyle='#dfedc8';ctx.font='18px sans-serif';ctx.textAlign='center';ctx.fillText('已暂停 · 空格继续',w/2,w/2);}
}
$('retry').onclick=reset;$('end-retry').onclick=reset;$('pause').onclick=pause;$('map').onchange=reset;$('new-seed').onclick=()=>{seed++;reset();};$('auto').onchange=()=>{$('auto').checked?startAuto():stopAuto();};['show-path','show-bonds','show-spins'].forEach(id=>$(id).onchange=draw);document.querySelectorAll('[data-dir]').forEach(b=>b.onclick=()=>act(b.dataset.dir));document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{lesson=b.dataset.lesson;reset();});$('next-lesson').onclick=()=>{const list=Object.keys(LESSONS);if(lesson==='relay'){$('map').value={neel:'wall',wall:'bend',bend:'neel'}[$('map').value];seed++;}else lesson=list[list.indexOf(lesson)+1];reset();};
const keymap={ArrowUp:'up',ArrowRight:'right',ArrowDown:'down',ArrowLeft:'left',w:'up',d:'right',s:'down',a:'left'};
window.addEventListener('keydown',e=>{if(['SELECT','TEXTAREA'].includes(document.activeElement?.tagName)||document.activeElement?.tagName==='INPUT'&&document.activeElement.type!=='checkbox')return;const d=keymap[e.key]||keymap[e.key.toLowerCase()];if(d){e.preventDefault();if(!e.repeat||performance.now()-lastMove>140)act(d);}else if(e.code==='Space'&&!['BUTTON','INPUT'].includes(document.activeElement?.tagName)){e.preventDefault();pause();}else if(e.key.toLowerCase()==='r')reset();});
let touch=null;canvas.addEventListener('pointerdown',e=>{touch={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointerup',e=>{if(!touch)return;const dx=e.clientX-touch.x,dy=e.clientY-touch.y;touch=null;if(Math.max(Math.abs(dx),Math.abs(dy))>15){act(Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up');return;}const r=canvas.getBoundingClientRect(),pad=r.width*.075,cell=(r.width-pad*2)/s.n,x=Math.floor((e.clientX-r.left-pad)/cell),y=Math.floor((e.clientY-r.top-pad)/cell),hx=s.head%s.n,hy=Math.floor(s.head/s.n);if(Math.abs(x-hx)+Math.abs(y-hy)===1)act(x>hx?'right':x<hx?'left':y>hy?'down':'up');});canvas.addEventListener('pointercancel',()=>{touch=null;});window.addEventListener('resize',draw);document.addEventListener('visibilitychange',()=>{if(document.hidden&&s.status==='playing'){setPause(s,true);stopAuto();render();}});reset();
